"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface LocateFixedIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface LocateFixedIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const LocateFixedIcon = forwardRef<LocateFixedIconHandle, LocateFixedIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) {
     controls.start("normal");
    } else {
     onMouseLeave?.(e as any);
    }
   },
   [controls, onMouseLeave],
  );

  const ringVariants: Variants = {
   normal: { scale: 1, opacity: 1 },
   animate: {
    scale: [1.4, 1],
    opacity: [0, 1],
    transition: { duration: 0.45 * duration, ease: [0.34, 1.2, 0.64, 1] },
   },
  };

  const tickVariants: Variants = {
   normal: { scale: 1, opacity: 1 },
   animate: (i: number) => ({
    scale: [1.8, 1],
    opacity: [0, 1],
    transition: {
     duration: 0.35 * duration,
     delay: (0.3 + i * 0.06) * duration,
     ease: [0.34, 1.2, 0.64, 1],
    },
   }),
  };

  const dotVariants: Variants = {
   normal: { scale: 1, opacity: 1 },
   animate: {
    scale: [0, 1.4, 1],
    opacity: [0, 1, 1],
    transition: {
     duration: 0.4 * duration,
     delay: 0.6 * duration,
     times: [0, 0.6, 1],
     ease: [0.34, 1.5, 0.64, 1],
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.circle
       cx="12"
       cy="12"
       r="7"
       variants={ringVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
      <m.line
       x1="2"
       y1="12"
       x2="5"
       y2="12"
       custom={0}
       variants={tickVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
      <m.line
       x1="19"
       y1="12"
       x2="22"
       y2="12"
       custom={1}
       variants={tickVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
      <m.line
       x1="12"
       y1="2"
       x2="12"
       y2="5"
       custom={2}
       variants={tickVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
      <m.line
       x1="12"
       y1="19"
       x2="12"
       y2="22"
       custom={3}
       variants={tickVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
      <m.circle
       cx="12"
       cy="12"
       r="3"
       variants={dotVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

LocateFixedIcon.displayName = "LocateFixedIcon";
export { LocateFixedIcon };
